import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.cNy3aYYk.js";const v=JSON.parse('{"title":"Tenant Live Chat API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant Live Chat API | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-live-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant Live Chat API | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-live-chat"}]]},"headers":[],"relativePath":"api/tenant-v1-live-chat.md","filePath":"api/tenant-v1-live-chat.md","lastUpdated":1794259478000}'),c={name:"api/tenant-v1-live-chat.md"};function i(n,e,r,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-live-chat-api" tabindex="-1">Tenant Live Chat API <a class="header-anchor" href="#tenant-live-chat-api" aria-label="Permalink to &quot;Tenant Live Chat API&quot;">​</a></h1><p>Module: <code>live-chat</code> <strong>2.1.0</strong> · Base: <code>/api/tenant/v1/live-chat</code> (authenticated) and <code>/api/public/live-chat/{publicKey}</code> (widget).</p><h2 id="public-widget" tabindex="-1">Public widget <a class="header-anchor" href="#public-widget" aria-label="Permalink to &quot;Public widget&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/public/live-chat/{publicKey}/bootstrap</code></td><td>Greeting, branding, suggested_replies, agent_display_name, show_powered_by, offline, within_hours, accepting_live, <strong>csat_enabled</strong>, <strong><code>departments</code></strong>, <strong><code>default_department_id</code></strong>, optional realtime</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/sessions</code></td><td>Returns <code>session_token</code> once (max body 64KB; throttle <code>live-chat-widget-session</code>); banned visitors/IPs → 403; optional <code>name</code>, <code>email</code>, <strong><code>phone</code></strong>, <code>page_url</code>, <code>page_title</code>, <code>referrer</code>, <code>screen</code>, <code>language</code>, <strong><code>client_id</code></strong> (when <code>require_prechat</code>, name/email/phone required)</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/heartbeat</code></td><td>Bearer session; updates presence/intel; optional <code>page_url</code>, <code>page_title</code>, <code>referrer</code>, <code>screen</code>, <code>language</code>; returns <code>open_conversation_uuid</code> when an open thread exists</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/identify</code></td><td>Bearer session; at least one of <code>name</code>, <code>email</code>, <strong><code>phone</code></strong>, <code>user_id</code>, <code>attributes</code> (max 20 keys)</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/conversations</code></td><td>Bearer session; open/create — requires <strong><code>name</code></strong>, <strong><code>email</code></strong>, <strong><code>phone</code></strong>, and <strong><code>department_id</code></strong> when active departments exist (else widget default); may be offline thread</td></tr><tr><td>GET</td><td><code>/api/public/live-chat/{publicKey}/conversations/{uuid}/messages</code></td><td>Poll with <code>since_id</code> (excludes <code>direction=note</code>; agent rows include <code>agent_name</code>)</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/conversations/{uuid}/messages</code></td><td>Visitor text or multipart attachment; offline leave-a-message when outside hours (same identity + department rules as open). Persist succeeds even if Reverb/notify fail (soft-fail).</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/conversations/{uuid}/typing</code></td><td>Bearer session; fans out <code>LiveChatTyping</code> (<code>direction=visitor</code>)</td></tr><tr><td>POST</td><td><code>/api/public/live-chat/{publicKey}/conversations/{uuid}/csat</code></td><td>Bearer session; body <code>score</code> (1–5 required), optional <code>comment</code> (max 2000); conversation must be closed</td></tr></tbody></table><p>Inactive widget → 404. Missing entitlement → 403. Bad/expired/revoked token → 401. CORS: Origin reflected for credential-less embeds.</p><p>The public embed (<code>public/widgets/live-chat.js?v=2.1.0</code>) always collects name, email, phone, and department before Start / Leave a message. It stores the session token in <code>localStorage</code> and resumes via heartbeat + message hydrate after page refresh. Send failures show an in-panel error with <strong>Retry</strong> (no browser <code>alert</code>). After close, CSAT UI appears when bootstrap <code>csat_enabled</code> is true.</p><h2 id="tenant-agent" tabindex="-1">Tenant agent <a class="header-anchor" href="#tenant-agent" aria-label="Permalink to &quot;Tenant agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/live-chat/widget</code></td><td><code>view</code> or <code>manage</code></td></tr><tr><td>PATCH</td><td><code>/live-chat/widget</code></td><td><code>manage</code> (includes suggested_replies, show_powered_by, agent_display_name, idle_minutes 0–1440, <strong><code>email_transcript_on_close</code></strong>, <strong><code>csat_enabled</code></strong>)</td></tr><tr><td>POST</td><td><code>/live-chat/widget/regenerate-key</code></td><td><code>manage</code></td></tr><tr><td>GET/POST/PATCH/DELETE</td><td><code>/live-chat/canned-replies</code></td><td><code>view</code> list; <code>manage</code> write</td></tr><tr><td>GET/POST/PATCH/DELETE</td><td><code>/live-chat/departments</code></td><td><code>view</code> list; <code>manage</code> write</td></tr><tr><td>GET</td><td><code>/live-chat/proactive-rules</code></td><td><code>view</code></td></tr><tr><td>POST/PATCH/DELETE</td><td><code>/live-chat/proactive-rules</code> · <code>/live-chat/proactive-rules/{id}</code></td><td><code>manage</code></td></tr><tr><td>GET</td><td><code>/live-chat/visitors/live</code></td><td><code>view</code> (<code>within</code> minutes, default 10)</td></tr><tr><td>GET</td><td><code>/live-chat/stats</code></td><td><code>view</code></td></tr><tr><td>GET</td><td><code>/live-chat/visitors/{id}/notes</code></td><td><code>view</code></td></tr><tr><td>POST/PATCH/DELETE</td><td><code>/live-chat/visitors/{id}/notes</code> · <code>…/notes/{noteId}</code></td><td><code>manage</code></td></tr><tr><td>POST</td><td><code>/live-chat/visitors/{id}/open-chat</code></td><td><code>reply</code> (optional <strong><code>body</code></strong> invite text; returns <code>message</code> when sent; fans out <code>LiveChatInvite</code>)</td></tr><tr><td>POST</td><td><code>/live-chat/visitors/{id}/ban</code> · <code>/unban</code></td><td><code>manage</code> (ban body: optional <code>reason</code>, optional <strong><code>ban_ip</code></strong> boolean)</td></tr><tr><td>GET</td><td><code>/live-chat/conversations</code></td><td><code>view</code> (filters: status, unread, my, assigned_to, department_id, is_offline, search — search matches visitor name/email/<strong>phone</strong>/page_url)</td></tr><tr><td>GET</td><td><code>/live-chat/conversations/{id}</code></td><td><code>view</code> (includes visitor intel including <strong><code>phone</code></strong> + CSAT fields when set)</td></tr><tr><td>GET</td><td><code>/live-chat/conversations/{id}/messages</code></td><td><code>view</code> (includes notes)</td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/read</code></td><td><code>view</code></td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/messages</code></td><td><code>reply</code> (optional attachment; <code>as_note</code> boolean; soft-fail realtime)</td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/typing</code></td><td><code>reply</code> (<code>LiveChatTyping</code> <code>direction=agent</code> for embed)</td></tr><tr><td>POST</td><td><code>/live-chat/conversations/{id}/escalate</code></td><td><code>reply</code> (+ Help Desk entitled)</td></tr><tr><td>PATCH</td><td><code>/live-chat/conversations/{id}</code></td><td>Policy: <code>assigned_to</code>, <code>status</code>, <code>lead_id</code>, <code>department_id</code></td></tr></tbody></table><p><code>{id}</code> accepts numeric id or conversation uuid.</p><h3 id="proactive-rule-body-create-update" tabindex="-1">Proactive rule body (create/update) <a class="header-anchor" href="#proactive-rule-body-create-update" aria-label="Permalink to &quot;Proactive rule body (create/update)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>widget_id</code></td><td>required on create</td></tr><tr><td><code>name</code></td><td>required string, max 255</td></tr><tr><td><code>is_active</code></td><td>optional boolean</td></tr><tr><td><code>path_contains</code></td><td>optional string, max 255</td></tr><tr><td><code>min_dwell_seconds</code></td><td>optional 0–86400</td></tr><tr><td><code>min_pages_viewed</code></td><td>optional 1–9999</td></tr><tr><td><code>message</code></td><td>required string, max 5000</td></tr><tr><td><code>cooldown_minutes</code></td><td>optional 1–10080</td></tr></tbody></table><h2 id="realtime-channels" tabindex="-1">Realtime channels <a class="header-anchor" href="#realtime-channels" aria-label="Permalink to &quot;Realtime channels&quot;">​</a></h2><ul><li><code>private-tenant.{tenantId}.live-chat.inbox</code></li><li><code>private-tenant.{tenantId}.live-chat.conversation.{uuid}</code></li><li>Public <code>live-chat.visitor.{uuid}</code> for embed</li></ul><p>Events: <code>LiveChatMessageSent</code>, <code>LiveChatConversationUpdated</code>, <code>LiveChatVisitorPresence</code>, <code>LiveChatTyping</code>, <code>LiveChatInvite</code> (public visitor channel — agent-initiated and proactive open/invite).</p><h2 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h2><p>Trigger key <strong><code>live_chat.proactive_invite_sent</code></strong> fires when a proactive rule opens a chat and sends an invite (same payload family as conversation events).</p>',16)])])}const u=t(c,[["render",i]]);export{v as __pageData,u as default};
